type Entry = { isFile: boolean; content: string; kids: Set<string> };

class MemoryFS {
  private map = new Map<string, Entry>([["/", { isFile: false, content: "", kids: new Set() }]]);

  // create every missing entry along the path; returns the entry for the path
  private ensure(path: string): Entry {
    const parts = path.split("/").filter(Boolean);
    let cur = "/";
    for (const name of parts) {
      const next = cur === "/" ? "/" + name : cur + "/" + name;
      if (!this.map.has(next)) {
        this.map.set(next, { isFile: false, content: "", kids: new Set() });
        this.map.get(cur)!.kids.add(name);
      }
      cur = next;
    }
    return this.map.get(cur)!;
  }

  listDir(path: string): string[] {
    const e = this.map.get(path)!;
    if (e.isFile) return [path.slice(path.lastIndexOf("/") + 1)];
    return [...e.kids].sort();
  }

  makeDir(path: string): void {
    this.ensure(path);
  }

  appendText(path: string, text: string): void {
    const e = this.ensure(path);
    e.isFile = true;
    e.content += text;
  }

  readText(path: string): string {
    return this.map.get(path)!.content;
  }
}

