        cur = "/"
        for name in filter(None, path.split("/")):
            nxt = "/" + name if cur == "/" else cur + "/" + name
            if nxt not in self.map:
                self.map[nxt] = {"file": False, "content": "", "kids": set()}
                self.map[cur]["kids"].add(name)
            cur = nxt
        return self.map[cur]

    def listDir(self, path: str) -> List[str]:
        e = self.map[path]
        if e["file"]:
            return [path.rsplit("/", 1)[1]]
        return sorted(e["kids"])

    def makeDir(self, path: str) -> None:
        self._ensure(path)

    def appendText(self, path: str, text: str) -> None:
        e = self._ensure(path)
        e["file"] = True
        e["content"] += text

    def readText(self, path: str) -> str:
        return self.map[path]["content"]

