class FsNode {
  kids = new Map<string, FsNode>();
  isFile = false;
  content: string[] = []; // appended pieces, joined on read
}

class MemoryFS {
  private root = new FsNode();

  private walk(path: string): FsNode {
    let node = this.root;
    for (const name of path.split("/")) {
      if (!name) continue;
      let next = node.kids.get(name);
      if (!next) { next = new FsNode(); node.kids.set(name, next); }
      node = next;
    }
    return node;
  }

  listDir(path: string): string[] {
    const node = this.walk(path);
    if (node.isFile) return [path.split("/").pop()!];
    return [...node.kids.keys()].sort();
  }

  makeDir(path: string): void {
    this.walk(path);
  }

  appendText(path: string, text: string): void {
    const node = this.walk(path);
    node.isFile = true;
    node.content.push(text);
  }

  readText(path: string): string {
    return this.walk(path).content.join("");
  }
}

