class FsNode:
    __slots__ = ("kids", "is_file", "content")

    def __init__(self):
        self.kids = {}
        self.is_file = False
        self.content = []


class MemoryFS:
    def __init__(self):
        self.root = FsNode()

    def _walk(self, path):
        node = self.root
        for name in path.split("/"):
            if name:
                node = node.kids.setdefault(name, FsNode())
        return node

    def listDir(self, path: str) -> List[str]:
        node = self._walk(path)
        if node.is_file:
            return [path.split("/")[-1]]
        return sorted(node.kids)

    def makeDir(self, path: str) -> None:
        self._walk(path)

    def appendText(self, path: str, text: str) -> None:
        node = self._walk(path)
        node.is_file = True
        node.content.append(text)

    def readText(self, path: str) -> str:
        return "".join(self._walk(path).content)

